// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        vm.prank(address(0));
        c.transferOwnership(address(this));

        bool ok;
        try c.owned{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        vm.prank(caller);
        bool ok2;
        try c.owned{gas: gasleft()}() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(ok2 == (caller == address(this)));
    }
}
